                    code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
                    severity: callisto_model::DiagnosticSeverity::Warning,
                    message: note,
                    package: None,
                    path: None,
                    escalated_by: None,
                    governed_by: None,
                });
